import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void max_reduce_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t outer_size,
    int64_t reduce_size,
    int64_t inner_size)
{
    int64_t total = outer_size * inner_size;
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int64_t outer_idx = idx / inner_size;
    int64_t inner_idx = idx % inner_size;

    const float* base = input + outer_idx * reduce_size * inner_size + inner_idx;

    float max_val = -FLT_MAX;
    int64_t k = 0;
    int64_t unroll_limit = reduce_size - (reduce_size % 8);
    for (; k < unroll_limit; k += 8) {
        float v0 = __ldg(&base[k * inner_size]);
        float v1 = __ldg(&base[(k + 1) * inner_size]);
        float v2 = __ldg(&base[(k + 2) * inner_size]);
        float v3 = __ldg(&base[(k + 3) * inner_size]);
        float v4 = __ldg(&base[(k + 4) * inner_size]);
        float v5 = __ldg(&base[(k + 5) * inner_size]);
        float v6 = __ldg(&base[(k + 6) * inner_size]);
        float v7 = __ldg(&base[(k + 7) * inner_size]);
        float m01 = fmaxf(v0, v1);
        float m23 = fmaxf(v2, v3);
        float m45 = fmaxf(v4, v5);
        float m67 = fmaxf(v6, v7);
        float m0123 = fmaxf(m01, m23);
        float m4567 = fmaxf(m45, m67);
        max_val = fmaxf(max_val, fmaxf(m0123, m4567));
    }
    for (; k < reduce_size; ++k) {
        float val = __ldg(&base[k * inner_size]);
        max_val = fmaxf(max_val, val);
    }

    output[idx] = max_val;
}

torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    input = input.contiguous();

    auto sizes = input.sizes();
    int64_t ndim = sizes.size();
    if (dim < 0) dim += ndim;

    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= sizes[i];

    int64_t reduce_size = sizes[dim];

    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];

    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }

    auto output = torch::empty(out_sizes, input.options());

    int64_t total = outer_size * inner_size;
    int threads = 256;
    int64_t blocks = (total + threads - 1) / threads;

    max_reduce_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size,
        reduce_size,
        inner_size
    );

    return output;
}
"""

max_reduce_header = r"""
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim);
"""

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=max_reduce_header,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        return max_reduce_module.max_reduce_cuda(x, self.dim)

